use crate::{model::*,unit_support::*};
#[test]fn wm026_destroy_transforms_same_instance_without_marker_reset(){let mut g=game();let id=field(&mut g,"WM026",0);{let c=g.board_mut(&id).unwrap();c.time_markers=2;c.shield=1;c.exhausted=true;}g.remove_dead(&id,RemovalCause::Destroy);g.drive().unwrap();for _ in 0..20{if g.stack.is_empty(){break}pass(&mut g);}let c=g.board(&id).expect("death replacement must retain the original board instance").1;assert_eq!(c.definition,"ZHWM026");assert_eq!(c.time_markers,2);assert_eq!(c.shield,1);assert!(c.exhausted);restore(&mut g);}
fn finish(g:&mut Game){g.drive().unwrap();for _ in 0..32{if let Some(p)=g.pending.clone(){choose(g,p.choice.options.iter().take(1).map(|o|o.id.clone()).collect());}else if g.stack.is_empty(){break}else{pass(g);}}assert!(g.stack.is_empty());restore(g);}
#[test]fn wm026_lethal_damage_survives_transform_and_mist_dies_once(){let mut g=game();let id=field(&mut g,"WM026",0);g.board_mut(&id).unwrap().damage=1;g.settle_deaths();assert!(g.board(&id).is_some());assert_eq!(g.wm026_pending.len(),1);g.settle_deaths();assert_eq!(g.wm026_pending.len(),1);finish(&mut g);assert!(g.board(&id).is_none());assert!(g.wm026_pending.is_empty());assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="WM026").count(),1);}
#[test]fn wm026_sublethal_damage_and_markers_survive(){let mut g=game();let id=field(&mut g,"WM026",0);{let c=g.board_mut(&id).unwrap();c.permanent_defense_markers=2;c.damage=1;c.time_markers=3;}g.remove_dead(&id,RemovalCause::Destroy);finish(&mut g);let c=g.board(&id).unwrap().1;assert_eq!(c.definition,"ZHWM026");assert_eq!((c.damage,c.permanent_defense_markers,c.time_markers),(1,2,3));}
#[test]fn wm026_pending_duplicate_or_missing_program_rejects_recovery(){let mut g=game();let id=field(&mut g,"WM026",0);g.remove_dead(&id,RemovalCause::Destroy);g.drive().unwrap();restore(&mut g);for n in 0..3{let mut x=g.clone();match n{0=>x.wm026_pending.push(x.wm026_pending[0].clone()),1=>x.stack.last_mut().unwrap().frame.as_mut().unwrap().steps.clear(),_=>x.wm026_pending.clear()};assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());let r=crate::room::RoomEnvelope::from_game(x);assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}}
#[test]fn wm026_prepare_three_qualifies_four_does_not(){for count in [3,4]{let mut g=game();let id=field(&mut g,"WM026",0);g.remove_dead(&id,RemovalCause::Destroy);finish(&mut g);for seat in (0..4).filter(|s|g.team(*s)!=g.team(0)).collect::<Vec<_>>(){g.players[seat].hand.clear();for _ in 0..count{let c=g.make_card("JC125",seat);g.players[seat].hand.push(c);}}g.turn+=1;g.begin_window(Window::Prepare);finish(&mut g);assert_eq!(g.board(&id).unwrap().1.definition,if count==3{"WM026"}else{"ZHWM026"});}}
#[test]fn wm026_response_departure_does_not_recreate_source(){let mut g=game();let id=field(&mut g,"WM026",0);g.remove_dead(&id,RemovalCause::Destroy);g.drive().unwrap();g.return_hand(&id);finish(&mut g);assert!(g.board(&id).is_none());assert_eq!(g.players[0].hand.iter().filter(|c|c.definition=="WM026").count(),1);assert!(g.wm026_pending.is_empty());}
#[test]fn wm026_elimination_discards_pending_event(){let mut g=game();let id=field(&mut g,"WM026",0);g.remove_dead(&id,RemovalCause::Destroy);g.drive().unwrap();g.eliminate(0);restore(&mut g);assert!(g.wm026_pending.is_empty());}
#[test]fn wm026_hidden_death_and_mist_return_use_printed_identity(){let mut g=game();let hidden=field(&mut g,"WM026",0);g.board_mut(&hidden).unwrap().face_down=true;g.remove_dead(&hidden,RemovalCause::Destroy);assert!(g.wm026_pending.is_empty());let id=field(&mut g,"WM026",0);g.remove_dead(&id,RemovalCause::Destroy);finish(&mut g);g.return_hand(&id);restore(&mut g);assert!(g.players[0].hand.iter().any(|c|c.definition=="WM026"));assert!(!g.players[0].hand.iter().any(|c|c.definition=="ZHWM026"));}
#[test]fn wm026_real_room_sacrifice_response_recovery_and_duplicate(){use crate::abi112_review_play_tests::Trace;let mut g=game();let id=field(&mut g,"WM026",0);fund(&mut g,0,"JC049",2);let spell=held(&mut g,"WM036",0);let mut t=Trace::new_preserving_rng(g,"wm026-prepared-real-sacrifice-response".into(),952);t.action(0,Action{card_id:Some(spell),..Action::new("play")});t.until_pending();t.choose(vec![id.clone()]);for _ in 0..40{if t.room.game.stack.is_empty()&&t.room.game.pending.is_none()&&t.room.pacing.window.is_none(){break}if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else{t.pass();}}assert_eq!(t.room.game.board(&id).unwrap().1.definition,"ZHWM026");assert!(t.room.game.wm026_pending.is_empty());let mut v=t.value();for step in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let duplicate=r.transition(step["seat"].as_u64().unwrap() as usize,Some(serde_json::from_value(step["command"].clone()).unwrap()),0).unwrap();assert_eq!(duplicate.outcome,"rejected");assert_eq!(duplicate.state,step["expected"]["state"]);assert!(!duplicate.changed&&duplicate.journal.is_empty());step["duplicate"]=serde_json::to_value(duplicate).unwrap();}stamp(&mut v);if let Ok(p)=std::env::var("WM026_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&v).unwrap()).unwrap();}}
#[test]fn wm026_natural_deck_deploy_sacrifice_and_prepare_return(){use crate::{catalog,deck,abi112_review_play_tests::Trace};fn start(seed:u64)->(Game,deck::DeckDraft){let mut d=deck::preset("watchers").unwrap();d.id="wm026-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[("WM026",3),("WM036",3),("JC029",3),("JC030",3),("JC049",3),("JC125",35)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if matches!(c.id.as_str(),"WM026"|"WM036"){c.supported=true;}}let d=deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("wm026-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
 let(seed,g,d)=(1..4097).find_map(|seed|{let(g,d)=start(seed);(["WM026","WM036","JC049"].iter().all(|id|g.players[0].hand.iter().any(|c|&c.definition==id))&&g.players[0].hand.iter().chain(g.players[0].deck.iter().take(5)).filter(|c|matches!(c.definition.as_str(),"JC029"|"JC030")).count()>=2&&g.players[0].hand.iter().chain(g.players[0].deck.iter().take(5)).filter(|c|c.definition=="JC049").count()>=2).then_some((seed,g,d))}).expect("seed with actual dealt source and assets");let mut t=Trace::new_preserving_rng(g,"wm026-natural-deck-transform-and-return".into(),953);let(mut original,mut cast,mut mist,mut returned)=(None::<String>,false,false,false);for step in 0..1800{if !cast {if let Some(c)=t.room.game.regions.iter().flat_map(|r|&r.cards).find(|c|c.definition=="WM026"&&c.controller==0){original=Some(c.id.clone());}}if step%300==0{eprintln!("natural step={step} turn={} assets={:?} hand={:?} original={:?}",t.room.game.turn,t.room.game.players[0].assets.iter().map(|c|&c.definition).collect::<Vec<_>>(),t.room.game.players[0].hand.iter().map(|c|&c.definition).collect::<Vec<_>>(),original);}if let Some(id)=&original{if let Some((_,c))=t.room.game.board(id){mist|=c.definition=="ZHWM026";returned|=mist&&c.definition=="WM026";}}if returned&&t.room.game.stack.is_empty()&&t.room.game.pending.is_none(){break}if let Some(p)=t.room.game.pending.clone(){if p.choice.kind=="damage"{let amount=p.choice.amount.unwrap_or(0);let allocations=p.choice.options.first().map(|o|std::collections::BTreeMap::from([(o.id.clone(),amount)])).unwrap_or_default();t.action(p.seat,Action{choice_id:Some(p.choice.id),allocations:Some(allocations),..Action::new("choose")});continue}if p.choice.kind=="investigation"{t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});continue}let ids=if p.choice.kind=="discard"{let mut options=p.choice.options.clone();options.sort_by_key(|o|!t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&c.definition=="JC125"));options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}else if p.choice.kind=="jc035-preparation-order"{p.choice.options.iter().filter(|o|original.as_ref()==Some(&o.id)).map(|o|o.id.clone()).take(1).collect()}else if p.choice.min.unwrap_or(0)>0&&p.seat==0&&p.choice.options.iter().any(|o|original.as_ref()==Some(&o.id)){vec![original.clone().unwrap()]}else{p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};t.choose(ids);continue}if !t.room.game.stack.is_empty(){t.pass();continue}let g=&t.room.game;let legal=g.legal_actions(0);let asset=legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&matches!(c.definition.as_str(),"JC029"|"JC030"|"JC049")&&g.players[0].assets.iter().filter(|a|catalog::card(&a.definition).color==catalog::card(&c.definition).color).count()<2)));let deploy=legal.iter().find(|a|original.is_none()&&a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="WM026")));let spell=legal.iter().find(|a|original.is_some()&&!cast&&a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="WM036")));if let Some(a)=asset.or(deploy).or(spell){let a=a.action.clone();if a.kind=="deploy"{original=a.card_id.clone();}cast|=a.kind=="play";t.action(0,a);continue}let other=(1..4).find_map(|seat|g.legal_actions(seat).into_iter().find(|a|a.action.kind=="deploy"&&g.players[seat].hand.len()>2).map(|a|(seat,a.action)));if let Some((seat,a))=other{t.action(seat,a);}else{t.pass();}}
 assert!(mist&&returned,"natural chain incomplete cast={cast} mist={mist} returned={returned}");let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":d,"privateCandidateRegistry":true});for step in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let duplicate=r.transition(step["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(step["command"].clone()).unwrap()),0).unwrap();assert_eq!(duplicate.state,step["expected"]["state"]);assert!(!duplicate.changed&&duplicate.journal.is_empty());step["duplicate"]=serde_json::to_value(duplicate).unwrap();}stamp(&mut v);if let Ok(p)=std::env::var("WM026_NATURAL_OUT"){std::fs::write(p,serde_json::to_vec(&v).unwrap()).unwrap();}}

fn stamp(v:&mut serde_json::Value){use sha2::{Digest,Sha256};let mut b=crate::bq052_tests::source_bindings();for(n,bytes)in[("rust-game/src/wm026.rs",include_bytes!("wm026.rs").as_slice()),("rust-game/src/wm026_tests.rs",include_bytes!("wm026_tests.rs").as_slice()),("rust-game/src/jc035.rs",include_bytes!("jc035.rs").as_slice()),("rust-game/src/mobility.rs",include_bytes!("mobility.rs").as_slice())]{b["files"][n]=format!("{:x}",Sha256::digest(bytes)).into();}v["sourceBindings"]=b;v["catalog"]=serde_json::to_value(crate::catalog::catalog()).unwrap();}

#[test]fn wm026_restart_clears_old_pending_transform(){let mut g=game();let id=field(&mut g,"WM026",0);g.remove_dead(&id,RemovalCause::Destroy);g.drive().unwrap();assert_eq!(g.wm026_pending.len(),1);g.start().unwrap();assert!(g.wm026_pending.is_empty());restore(&mut g);let room=crate::room::RoomEnvelope::from_game(g);crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).unwrap();}
